#!/usr/bin/env bash\n\n# Mock rationale: Simple mapping without external dependencies\n\ntype="$1"\ncase "$type" in\n  feat) emoji="✨";;\n  fix) emoji="🐛";;\n  docs) emoji="📚";;\n  chore) emoji="🧹";;\n  refactor) emoji="🔧";;\n  test) emoji="✅";;\n  style) emoji="💄";;\n  perf) emoji="⚡";;\n  build) emoji="🏗️";;\n  ci) emoji="🤖";;\n  revert) emoji="⏪";;\n  *) emoji="❓";;\nesac\n\n# Write the result to the GitHub Actions output file\n# Mock rationale: Directly appending ensures compatibility with the composite action step\n\necho "emoji=$emoji" >> "$GITHUB_OUTPUT"
